def _lifesteal(self, p, dmg, x=None, z=None, show=False):
    """★ round586：只要造成伤害就按全能吸血回血（0 不显示 +0）"""
    try:
        if p is None or int(dmg) <= 0:
            return 0
        pct = self._omni_pct(p)
        if pct <= 0:
            return 0
        heal = int(round(float(dmg) * pct))
