_sk_b_canfire:
def _sk_b_canfire(self, p, key, cd):
    t = getattr(p, 'skBT', None)
    if t is None:
        p.skBT = {}
        t = p.skBT
    # ★ round578：0 CD 的技能（嗜血/坦克）不能被残留的 skBT 卡住 ✓
    if cd > 0:
        if t.get(key, 0) > 0:
            return False
        t[key] = cd
    else:
        t.pop(key, None)
    return True

